package com.example.lending.adapter.out.persistence;

import com.example.lending.application.port.out.LoadLoanHistoryPort;
import org.springframework.stereotype.Component;

import java.util.List;
import java.util.Map;
import java.util.UUID;
import java.util.stream.Collectors;

@Component
public class LoanHistoryQueryAdapter implements LoadLoanHistoryPort {

    private final LoanJpaRepository loanJpaRepository;
    private final BookJpaRepository bookJpaRepository;
    private final LoanMapper loanMapper = new LoanMapper();

    public LoanHistoryQueryAdapter(LoanJpaRepository loanJpaRepository, BookJpaRepository bookJpaRepository) {
        this.loanJpaRepository = loanJpaRepository;
        this.bookJpaRepository = bookJpaRepository;
    }

    @Override
    public List<LoanHistoryEntry> loadLoanHistory(UUID memberId) {
        List<LoanJpaEntity> loans = loanJpaRepository.findByMemberIdOrderByLoanedAtDescIdDesc(memberId);
        Map<UUID, String> titles = bookJpaRepository.findAllById(
                        loans.stream().map(LoanJpaEntity::getBookId).collect(Collectors.toSet())).stream()
                .collect(Collectors.toMap(BookJpaEntity::getId, BookJpaEntity::getTitle));
        return loans.stream()
                .map(loan -> new LoanHistoryEntry(loanMapper.toDomain(loan), titles.get(loan.getBookId())))
                .toList();
    }
}
