package com.example.lending;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import java.util.Map;
import java.util.UUID;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class LoanHistoryIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void member_without_loans_gets_an_empty_history() throws Exception {
        String memberId = registerMember();

        mockMvc.perform(get("/members/{memberId}/loans/history", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$").isEmpty());
    }

    @Test
    void history_includes_returned_loans_newest_first_with_late_fee() throws Exception {
        String memberId = registerMember();
        String older = borrow(registerBook("History Older Clean Code"), memberId, "2026-03-02");
        borrow(registerBook("History Newer Refactoring"), memberId, "2026-03-10");
        mockMvc.perform(post("/loans/{loanId}/return", older)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"returnedAt\":\"2026-03-21\"}"))
                .andExpect(status().isOk());

        mockMvc.perform(get("/members/{memberId}/loans/history", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(2))
                .andExpect(jsonPath("$[0].title").value("History Newer Refactoring"))
                .andExpect(jsonPath("$[0].loanedAt").value("2026-03-10"))
                .andExpect(jsonPath("$[0].returnedAt").doesNotExist())
                .andExpect(jsonPath("$[0].lateFee").doesNotExist())
                .andExpect(jsonPath("$[1].title").value("History Older Clean Code"))
                .andExpect(jsonPath("$[1].loanedAt").value("2026-03-02"))
                .andExpect(jsonPath("$[1].returnedAt").value("2026-03-21"))
                .andExpect(jsonPath("$[1].lateFee").value(500));
    }

    @Test
    void unknown_member_returns_404() throws Exception {
        mockMvc.perform(get("/members/{memberId}/loans/history", UUID.randomUUID().toString()))
                .andExpect(status().isNotFound());
    }

    private String borrow(String bookId, String memberId, String loanedAt) throws Exception {
        String body = mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(Map.of(
                                "bookId", bookId, "memberId", memberId, "loanedAt", loanedAt))))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(body).get("loanId").asText();
    }

    private String registerMember() throws Exception {
        String body = mockMvc.perform(post("/members")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"임다온\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(body).get("memberId").asText();
    }

    private String registerBook(String title) throws Exception {
        String body = mockMvc.perform(post("/books")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"" + title + "\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(body).get("id").asText();
    }
}
